<script setup>import { onMounted, reactive, ref } from "vue"; import AdminLayout from "../../layouts/AdminLayout.vue"; import MaterialCard from "../../components/MaterialCard.vue"; import { materialService } from "../../services/api"; const items = ref([]), error = ref(""), editing = ref(null); const form = reactive({ nom: "", categorie: "Ordinateur", description: "", quantite_totale: 0, quantite_disponible: 0, statut: "disponible" }); const load = async () => { try { items.value = (await materialService.list()).data; } catch (exception) { error.value = exception.message; } }; const open = (item = null) => { editing.value = item; Object.assign(form, item || { nom: "", categorie: "Ordinateur", description: "", quantite_totale: 0, quantite_disponible: 0, statut: "disponible" }); document.getElementById("material-modal").showModal(); }; const save = async () => { if (form.quantite_disponible > form.quantite_totale) { error.value = "La quantité disponible ne peut pas dépasser la quantité totale."; return; } try { const payload = { ...form, quantite_totale: Number(form.quantite_totale), quantite_disponible: Number(form.quantite_disponible) }; if (editing.value) await materialService.update(editing.value.id, payload); else await materialService.create(payload); document.getElementById("material-modal").close(); await load(); } catch (exception) { error.value = exception.message; } }; onMounted(load);</script><template><AdminLayout><section class="p-5 md:p-10"><div class="flex items-center justify-between"><div><h1 class="text-3xl font-bold">Matériels</h1><p class="mt-2 text-slate-500">Gérez le parc informatique.</p></div><button class="btn border-0 bg-[#17482d] text-white" @click="open()">Ajouter</button></div><div v-if="error" class="alert alert-error mt-5">{{ error }}</div><div class="mt-7 grid gap-5 sm:grid-cols-2 xl:grid-cols-3"><MaterialCard v-for="item in items" :key="item.id" :material="item" admin @edit="open" /></div><dialog id="material-modal" class="modal"><div class="modal-box"><h3 class="text-lg font-bold">{{ editing ? 'Modifier' : 'Ajouter' }} un matériel</h3><form class="mt-4 grid gap-3" @submit.prevent="save"><input v-model="form.nom" class="input input-bordered" placeholder="Nom" required><input v-model="form.categorie" class="input input-bordered" placeholder="Catégorie" required><textarea v-model="form.description" class="textarea textarea-bordered" placeholder="Description"></textarea><input v-model.number="form.quantite_totale" type="number" min="0" class="input input-bordered" placeholder="Quantité totale" required><input v-model.number="form.quantite_disponible" type="number" min="0" class="input input-bordered" placeholder="Quantité disponible" required><select v-model="form.statut" class="select select-bordered"><option value="disponible">Disponible</option><option value="maintenance">Maintenance</option><option value="retire">Retiré</option></select><button class="btn border-0 bg-[#17482d] text-white">Enregistrer</button></form></div></dialog></section></AdminLayout></template>
